This C program undercounts words when a line ends without whitespace. Fix the bug with the smallest change and print the whole corrected program in a code block.

```c
#include <stdio.h>
#include <string.h>

static int count_words(const char *s) {
    int n = 0, in_word = 0;
    for (size_t i = 0; i <= strlen(s); i++) {
        char c = s[i];
        if (c == ' ' || c == '\t' || c == '\n') {
            if (in_word) n++;
            in_word = 0;
        } else {
            in_word = 1;
        }
    }
    return n;
}

int main(void) {
    const char *lines[] = {"hello world", "  leading spaces", "trailing   ", "one"};
    for (int i = 0; i < 4; i++)
        printf("%d: %d\n", i, count_words(lines[i]));
    return 0;
}
```

